 ids=[x['player_master_id'] for x in selected];hid=matchup.replace('@','_')+'_primary';sids=['salary','stats','snaps','aliases','web_'+away,'web_'+home]
 if matchup=='CAR@PHI':sids.append('web_PHI_home')
 if matchup=='NYJ@NE':sids.append('web_NE_NFL')
 h={'hypothesis_id':hid,'game_id':gid,'formats':['CLASSIC'],'player_master_ids':ids,'status':'research_only','action':'none','hypothesis':title,'supporting_evidence':[evidence],'contrary_evidence':[contrary],'conditional_assumptions':['Selected players must be active and confirmed role/starting identities retained; scenario is conditional, not reported forecast.'],'testable_implication':mechanism,'unknowns':['No Sunday projection snapshot to establish quantified model disagreement.','Final Week 6 injuries, current depth and fresh observed market/weather incomplete.','No measured complete pregame team targets/carries allocation; no concentration/transfer runtime assumptions allowed.'],'source_ids':sids,'uncertainty':'Uncalibrated provisional football judgment; sensitivity factor and elasticity are designed bounds, not measured effects or probabilities.','numeric_effect_proposal':None,'expires_at':expiry,'recheck_triggers':['Wednesday practice reports','Final game designations/inactives','Starting QB confirmation','New projection/context/market snapshot','Source or slate correction']};hypotheses.append(h)
 assessment={'assessment_id':hid+'_judgment','kind':'subjective_analyst_judgment','status':'research_only','production_action':'none','game_id':gid,'formats':['CLASSIC'],'player_master_ids':ids,'source_ids':sids,'source_hypothesis_ids':[hid],'factual_premises':[],'lean':lean,'supporting_reasoning':mechanism,'contrary_evidence':[contrary],'conditions':h['conditional_assumptions'],'strongest_alternative':'Opposite passing/rushing game flow; no primary thesis is forced jointly with its contrary outcome.','construction_implications':[{'action':'shadow_comparison_only','format':'CLASSIC','type':'player_emphasis','roles':{'PLAYER':ids[:3]}}],'what_changes_view':h['recheck_triggers'],'confidence_label':'Provisional; ordinal preference only','numeric_effect_proposal':None,'selection_weight':None,'expires_at':expiry};assessments.append(assessment)
 reviews.append({'matchup':matchup,'game_id':gid,'headline':title,'lean':lean,'evidence':evidence,'mechanism':mechanism,'contrary':contrary,'selected_players':selected,'primary_assumption':{'kind':kind,'game_id':gid,'team':team,'factor':factor,'elasticity':0.5},'hypothesis_id':hid})
